INSERT INTO `message` VALUES (1,1,2,3,'在吗？想请教你一个问题。',1,'2026-09-12 00:23:58.997',0,'2026-09-11 22:23:58.997','2026-09-12 10:23:59.038'),(2,1,3,2,'在的，你说。',1,'2026-09-11 23:23:58.997',0,'2026-09-11 23:23:58.997','2026-09-12 10:23:59.038'),(3,1,2,3,'MySQL 的分页查询有没有推荐写法？',1,'2026-09-12 00:23:58.997',0,'2026-09-12 00:23:58.997','2026-09-12 10:23:59.038'),(4,1,3,2,'ORDER BY 带上主键，然后限制 size。',1,'2026-09-12 01:23:58.997',0,'2026-09-12 01:23:58.997','2026-09-12 10:23:59.038'),(5,1,2,3,'为什么必须带主键？',1,'2026-09-12 02:23:58.997',0,'2026-09-12 02:23:58.997','2026-09-12 10:23:59.038'),(6,1,3,2,'因为 create_time 可能重复，排序不稳定。',1,'2026-09-12 03:23:58.997',0,'2026-09-12 03:23:58.997','2026-09-12 10:23:59.038'),(7,1,2,3,'明白了，谢谢！',1,'2026-09-12 04:23:58.997',0,'2026-09-12 04:23:58.997','2026-09-12 10:23:59.038'),(8,1,3,2,'不客气。',1,'2026-09-12 05:23:58.997',0,'2026-09-12 05:23:58.997','2026-09-12 10:23:59.038'),(9,1,3,2,'对了，周末有空吗？想约你一起看展。',1,'2026-09-12 17:29:13.798',0,'2026-09-12 07:23:58.997','2026-09-12 17:29:13.799'),(10,1,3,2,'好的，那就这么定了。',1,'2026-09-12 17:29:13.798',0,'2026-09-12 08:23:58.997','2026-09-12 17:29:13.799'),(11,5,7,5,'这是会话 5 的第 1 条测试消息。',1,'2026-09-12 04:23:58.997',0,'2026-09-09 16:23:58.997','2026-09-12 10:23:59.041'),(12,4,6,4,'这是会话 4 的第 1 条测试消息。',1,'2026-09-12 05:23:58.997',0,'2026-09-10 04:23:58.997','2026-09-12 10:23:59.041'),(13,3,5,3,'这是会话 3 的第 1 条测试消息。',1,'2026-09-12 06:23:58.997',0,'2026-09-10 16:23:58.997','2026-09-12 10:23:59.041'),(14,2,4,2,'这是会话 2 的第 1 条测试消息。',1,'2026-09-12 07:23:58.997',0,'2026-09-11 04:23:58.997','2026-09-12 10:23:59.041'),(15,5,5,7,'这是会话 5 的第 2 条测试消息。',1,'2026-09-12 03:23:58.997',0,'2026-09-09 10:23:58.997','2026-09-12 10:23:59.041'),(16,4,4,6,'这是会话 4 的第 2 条测试消息。',1,'2026-09-12 04:23:58.997',0,'2026-09-09 22:23:58.997','2026-09-12 10:23:59.041'),(17,3,3,5,'这是会话 3 的第 2 条测试消息。',1,'2026-09-12 05:23:58.997',0,'2026-09-10 10:23:58.997','2026-09-12 10:23:59.041'),(18,2,2,4,'这是会话 2 的第 2 条测试消息。',1,'2026-09-12 06:23:58.997',0,'2026-09-10 22:23:58.997','